toolCall.argumentsJson:
{"CommandLine":"$paths = @("C:\Users\footb", "C:\Program Files", "C:\Program Files (x86)", "C:\ProgramData")
foreach ($p in $paths) {
    Get-ChildItem -Path $p -Directory -ErrorAction SilentlyContinue | ForEach-Object {
        $size = (Get-ChildItem -Path $_.FullName -Recurse -File -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
        [PSCustomObject]@{
            Path = $_.FullName
            "Size(GB)" = [math]::Round($size / 1GB, 2)
        }
    } | Sort-Object "Size(GB)" -Descending | Select-Object -First 5
}","Cwd":"C:\Users\footb","WaitMsBeforeAsync":10000,"toolAction":"Checking largest directories on C: drive","toolSummary":"Find largest folders"}
